 <!-- Ring Oxygen -->\n  <circle cx=\"410\" cy=\"62\" r=\"10.5\" fill=\"#070a14\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n  <text x=\"410\" y=\"66\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"11\" font-weight=\"bold\">O</text>\n  <!-- Substituent CH2OH at C5 -->\n  <line x1=\"470\" y1=\"85\" x2=\"470\" y2=\"52\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n  <text x=\"470\" y=\"44\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">CH₂OH</text>\n  <!-- Substituent CH2OH at C2 -->\n  <line x1=\"350\" y1=\"85\" x2=\"350\" y2=\"52\" stroke=\"#94a3b8\" stroke-width=\"1.8\"/>\n  <text x=\"350\" y=\"44\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">CH₂OH</text>\n  <!-- Ring Label -->\n  <text x=\"410\" y=\"106\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"12\" font-weight=\"bold\">Gốc β-fructose</text>\n  <text x=\"410\" y=\"122\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"10\">(Dạng furanose)</text>\n  <!-- C2 vertex marker -->\n  <circle cx=\"350\" cy=\"85\" r=\"5.5\" fill=\"#fbbf24\" stroke=\"#070a14\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"73\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"bold\">C2</text>\n\n  <!-- ================= CẦU NỐI GLYCOSIDE (C1 - O - C2) ================= -->\n  <!-- Left arm from C1(175, 85) to O(262, 120) -->\n  <line x1=\"175\" y1=\"85\" x2=\"249\" y2=\"115\" stroke=\"#fbbf24\" stroke-width=\"2.8\" stroke-linecap=\"round\"/>\n  <!-- Right arm from O(262, 120) to C2(350, 85) -->\n  <line x1=\"275\" y1=\"115\" x2=\"350\" y2=\"85\" stroke=\"#fbbf24\" stroke-width=\"2.8\" stroke-linecap=\"round\"/>\n  <!-- Bridge Oxygen atom -->\n  <circle cx=\"262\" cy=\"120\" r=\"14\" fill=\"#070a14\" stroke=\"#f43f5e\" stroke-width=\"2.5\"/>\n  <text x=\"262\" y=\"125\" text-anchor=\"middle\" fill=\"#f43f5e\" font-size=\"13\" font-weight=\"bold\">O</text>\n  <!-- Educational Label (No Answer Leak) -->\n  <text x=\"262\" y=\"150\" text-